import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"烦恼","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-烦恼.md","filePath":"50-概念资料/dict-烦恼.md","lastUpdated":null}'),d={name:"50-概念资料/dict-烦恼.md"};function l(i,t,h,n,u,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="烦恼" tabindex="-1">烦恼 <a class="header-anchor" href="#烦恼" aria-label="Permalink to &quot;烦恼&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>烦恼在佛学中指扰乱身心、使人不得安宁的负面心理状态。了空士的独特看法：<strong>烦恼不是敌人，是修行的信号和机会</strong>。</p><h2 id="了空士原话" tabindex="-1">了空士原话 <a class="header-anchor" href="#了空士原话" aria-label="Permalink to &quot;了空士原话&quot;">​</a></h2><blockquote><p>&quot;烦恼即菩提——烦恼不是敌人，它是你修行的机会。每一次烦恼来的时候，就是你进步的契机。&quot;</p></blockquote><blockquote><p>&quot;一切烦恼为如来种——烦恼是觉悟的种子，不是敌人。&quot;</p></blockquote><blockquote><p>&quot;不怕念起，只怕觉迟。烦恼来了，不是压制它，也不是随它去。是——看清楚它，然后做该做的事。&quot;</p></blockquote><h2 id="了空士对烦恼的两大分类" tabindex="-1">了空士对烦恼的两大分类 <a class="header-anchor" href="#了空士对烦恼的两大分类" aria-label="Permalink to &quot;了空士对烦恼的两大分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>来源</th><th>对治</th></tr></thead><tbody><tr><td>对未来的烦恼（焦虑）</td><td>执着于未发生的相</td><td>对境不住</td></tr><tr><td>对他人的烦恼（愤怒/嫉妒）</td><td>我相未破</td><td>对法不执</td></tr><tr><td>对结果的烦恼（得失）</td><td>执着于结果</td><td>圆融中和 + 自然务实</td></tr><tr><td>对自身的烦恼（自责/自卑）</td><td>我执过重</td><td>过心不可得</td></tr></tbody></table><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><p>烦恼不是用来&quot;消灭&quot;的——<strong>消灭烦恼的念头本身也是烦恼</strong>。烦恼来了，知道它来了，观察它，然后该做什么就做什么。</p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-菩提">菩提</a> — 烦恼转过来就是菩提</li><li><a href="/50-概念资料/dict-清净心">清净心</a> — 不被烦恼污染的本来状态</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/model-历境炼心">历境炼心</a> — 在烦恼中修行的核心模型</li><li><a href="/model-对境不住">对境不住</a> — 不被烦恼带跑</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>烦恼来时问自己：&quot;我在烦恼什么？&quot;</li><li>不批判情绪——&quot;我不应该有这种情绪&quot;是第二层烦恼</li><li>观察烦恼、接纳烦恼、转化烦恼</li></ul>',17)])])}const b=a(d,[["render",l]]);export{q as __pageData,b as default};
